create table public.avuhz_diagnostic_agreement_authorities (diagnostic_agreement_authority_id uuid primary key, tenant_id uuid not null, engagement_id uuid not null, agreement_type text not null check (agreement_type='DIAGNOSTIC_OIA'), agreement_reference text not null check (char_length(agreement_reference) between 1 and 200), status text not null check (status='VERIFIED_ACTIVE'), diagnostic_scope_id uuid not null, scope_version integer not null check (scope_version>=1), canonical_scope_digest text not null check (canonical_scope_digest ~ '^sha256:[0-9a-f]{64}$'), effective_at timestamptz not null, ends_at timestamptz, verified_at timestamptz not null, recorded_at timestamptz not null, record_version integer not null check (record_version>=1), created_at timestamptz not null default now(), unique (tenant_id,diagnostic_agreement_authority_id), unique (tenant_id,diagnostic_agreement_authority_id,record_version), check (ends_at is null or ends_at>effective_at), foreign key (tenant_id,engagement_id) references public.avuhz_engagements (tenant_id,engagement_id), foreign key (tenant_id,diagnostic_scope_id,scope_version) references public.avuhz_diagnostic_scopes (tenant_id,diagnostic_scope_id,scope_version)); create table public.avuhz_diagnostic_payment_verifications (diagnostic_payment_verification_id uuid primary key, tenant_id uuid not null, engagement_id uuid not null, diagnostic_agreement_authority_id uuid not null, diagnostic_agreement_authority_version integer not null check (diagnostic_agreement_authority_version>=1), payment_purpose text not null check (payment_purpose='DIAGNOSTIC_OIA'), verification_status text not null check (verification_status in ('VERIFIED','INVALIDATED')), provider_reference text not null check (char_length(provider_reference) between 1 and 200), amount_minor bigint not null check (amount_minor>=1), currency char(3) not null check (currency ~ '^[A-Z]{3}$'), verified_at timestamptz not null, invalidated_at timestamptz, record_version integer not null check (record_version>=1), created_at timestamptz not null default now(), unique (tenant_id,diagnostic_payment_verification_id), check ((verification_status='VERIFIED' and invalidated_at is null) or (verification_status='INVALIDATED' and invalidated_at is not null)), foreign key (tenant_id,engagement_id) references public.avuhz_engagements (tenant_id,engagement_id), foreign key (tenant_id,diagnostic_agreement_authority_id) references public.avuhz_diagnostic_agreement_authorities (tenant_id,diagnostic_agreement_authority_id));
